INSERT OR REPLACE INTO cards (id, name, name_cn, name_jp, type, race, attribute, level, atk, def, desc_cn) VALUES
(847915, 'Number Wall', '号数之壁', 'ナンバーズ・ウォール', 'Trap Card', 'Continuous', NULL, NULL, NULL, NULL, '自己场上有名字带有「No.」的怪兽存在的场合才能发动。只要这张卡在场上存在，双方场上的名字带有「No.」的怪兽不会被卡的效果破坏，不会被和名字带有「No.」的怪兽以外的战斗破坏。自己场上的名字带有「No.」的怪兽被破坏时，这张卡破坏。'),
(21858819, 'Number XX: Utopic Dark Infinity', 'No.XX 无限之达克霍普', 'No.XX インフィニティ・ダークホープ', 'XYZ Monster', 'Warrior', 'DARK', 10, 4000, 4000, '10星怪兽×2只以上 这个卡名的①②的效果1回合各能使用1次。 ①：自己或者对方的怪兽被战斗破坏送去墓地时，把这张卡1个超量素材取除，以那1只怪兽为对象才能发动。那只怪兽在自己场上守备表示特殊召唤。 ②：以这张卡以外的自己场上1只特殊召唤的表侧表示怪兽为对象才能发动。自己基本分回复那只怪兽的原本攻击力的数值。'),
(20994205, 'Numbers Eveil', '编号系觉醒', 'ナンバーズ・エヴァイユ', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '①：从额外卡组特殊召唤的怪兽只有对方场上才存在的场合才能发动。从额外卡组选4只「No.」超量怪兽（相同阶级最多1只）。「No.」数值和那4只的合计相同的1只「No.」超量怪兽当作超量召唤从额外卡组特殊召唤，把选的怪兽全部作为那只怪兽的超量素材。只要这个效果特殊召唤的怪兽在自己场上表侧表示存在，自己不是「No.」超量怪兽不能特殊召唤。'),
(4606229, 'Numbers Last Hope', '最后的希望号数', '最後の希望', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名在规则上也当作「银河眼」卡使用。这个卡名的卡在1回合只能发动1张。 ①：把基本分支付一半，以自己墓地2只怪兽为对象才能发动。那2只怪兽效果无效特殊召唤，只用那2只为素材把1只「No.」超量怪兽超量召唤。这张卡的发动后，直到回合结束时自己除这个效果的超量召唤以外只能有1次从额外卡组把怪兽特殊召唤。'),
(97738431, 'Numbers Overlay Boost', '编号系叠光推进', 'ナンバーズ・オーバーレイ・ブースト', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '选择自己场上1只没有超量素材的名字带有「No.」的超量怪兽才能发动。把自己手卡2只怪兽在选择的超量怪兽下面重叠作为超量素材。'),
(68630939, 'Numbers Protection', '号数守护', 'ナンバーズ・プロテクト', 'Trap Card', 'Counter', NULL, NULL, NULL, NULL, '这个卡名的①②的效果1回合只能有1次使用其中任意1个。 ①：自己场上有「No.」超量怪兽存在，怪兽的效果·魔法·陷阱卡发动时才能发动。那个发动无效并破坏。 ②：这张卡在墓地存在的状态，自己场上的表侧表示的「No.」超量怪兽被战斗·效果破坏的场合才能发动。这张卡在自己场上盖放。这个效果盖放的这张卡从场上离开的场合除外。'),
(92065772, 'Numbing Grub in the Ice Barrier', '栖居冰结界的魔醉虫', '氷結界に住む魔酔虫', 'Effect Monster', 'Insect', 'WATER', 4, 1300, 1800, '①：这张卡召唤的场合，指定没有使用的主要怪兽区域1处发动。这张卡得到以下效果。 ●只要这张卡在怪兽区域存在，指定的区域不能使用。'),
(83061014, 'Numen erat Testudo', '后被称为龟的神', '後に亀と呼ばれる神', 'Effect Monster', 'Aqua', 'WATER', 5, 1800, NULL, '只要这张卡在场上表侧表示存在，双方不能把攻击力1800以下的怪兽特殊召唤。'),
(37115973, 'Numeral Hunter', '编号系猎人', 'ナンバーズハンター', 'Effect Monster', 'Warrior', 'LIGHT', 4, 1600, 1400, '①：这张卡召唤·反转召唤·特殊召唤成功的场合发动。场上的「No.」超量怪兽全部回到持有者的额外卡组。 ②：只要这张卡在怪兽区域存在，双方不能把「No.」超量怪兽特殊召唤。此外，这张卡不会被和超量怪兽的战斗破坏，不受超量怪兽的效果影响。'),
(77402960, 'Numeron Calling', '源数直系', 'ヌメロン・ダイレクト', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '①：自己的场地区域有「源数网络」存在，自己场上没有怪兽存在的场合才能发动。从额外卡组把最多4只「源数之门」超量怪兽特殊召唤（同名卡最多1张）。这个效果特殊召唤的怪兽在结束阶段除外。这个效果的发动后，直到回合结束时自己只能有1次把怪兽召唤·特殊召唤。'),
(41850466, 'Numeron Chaos Ritual', '源数混沌仪式', 'ヌメロン・カオス・リチューアル', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '①：自己场上的表侧表示的「混沌No.1 混沌源数门-空」被怪兽的效果破坏的回合，从自己墓地的卡以及除外的自己的卡之中以1张「源数网络」和4只「No.」超量怪兽为对象才能发动。从额外卡组把1只「混沌No.1000 梦幻虚神 原数天灵」变成攻击力10000/守备力1000特殊召唤，把作为对象的5张卡作为那超量素材。这个效果的发动后，直到回合结束时自己只能有1次把怪兽召唤·特殊召唤。'),
(46382143, 'Numeron Creation', '源数创造', 'ヌメロン・クリエイション', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名在规则上也当作「银河眼」卡使用。这个卡名的效果1回合只能适用1次。 ①：原本攻击力是3000以上的龙族·光属性怪兽在场上有3只以上存在的场合才能发动。从额外卡组把1只龙族「No.」超量怪兽特殊召唤。那之后，把场上的这张卡在那只怪兽下面重叠作为超量素材。'),
(41418852, 'Numeron Network', '源数网络', 'ヌメロン・ネットワーク', 'Spell Card', 'Field', NULL, NULL, NULL, NULL, '这个卡名的①的效果1回合只能使用1次。 ①：自己主要阶段，把满足发动条件的1张「源数」通常魔法卡从卡组送去墓地才能发动。这个效果变成和那张魔法卡发动时的效果相同。 ②：只要这张卡在场地区域存在，自己场上的「源数」超量怪兽把超量素材取除来让效果发动的场合，也能不把超量素材取除来发动。'),
(20936251, 'Numeron Storm', '源数风暴', 'ヌメロン・ストーム', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '①：自己场上有「原数天灵」怪兽存在的场合才能发动。对方场上的魔法·陷阱卡全部破坏，给与对方1000伤害。'),
(42352091, 'Numeron Wall', '源数之壁', 'ヌメロン・ウォール', 'Effect Monster', 'Fiend', 'DARK', 1, NULL, NULL, '这个卡名的①的效果1回合只能使用1次。 ①：「源数之壁」以外的卡不在自己场上存在的场合，把手卡·场上的这张卡送去墓地才能发动。从手卡·卡组选1张「源数网络」发动。这个效果在对方回合也能发动。 ②：自己受到战斗伤害时才能发动。这张卡从手卡特殊召唤，那次伤害步骤结束后战斗阶段结束。'),
(2130625, 'Numinous Healer', '白衣天使', '白衣の天使', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '自己因战斗或者卡的效果受到伤害时才能发动。自己回复1000基本分。自己墓地有「白衣天使」存在的场合，再回复那个数量的500基本分。'),
(36010310, 'Nunu, the Ogdoadic Remnant', '溟界之滓－努泸', '溟界の滓－ヌル', 'Effect Monster', 'Reptile', 'LIGHT', 4, NULL, NULL, '这个卡名的①②的效果1回合各能使用1次。 ①：把这张卡从手卡送去墓地才能发动。从卡组把1只爬虫类族·暗属性怪兽送去墓地。 ②：自己场上没有怪兽存在的场合或者有「溟界」怪兽存在的场合才能发动。这张卡从墓地特殊召唤。这个效果特殊召唤的这张卡从场上离开的场合除外。只要这个效果特殊召唤的这张卡在怪兽区域表侧表示存在，自己不是爬虫类族怪兽不能特殊召唤。'),
(60681372, 'Nurikabe', '妖魔 涂壁', '妖魔ヌリカベ', 'Effect Monster', 'Zombie', 'EARTH', 4, 900, 2000, '这个卡名的效果1回合只能使用1次。 ①：这个回合没有送去墓地的这张卡在墓地存在的场合，支付1000基本分，以自己墓地1只其他的不死族怪兽为对象才能发动。那只怪兽和这张卡特殊召唤。这个效果特殊召唤的怪兽的效果无效化，从场上离开的场合除外。'),
(40398073, 'Nurse Dragonmaid', '龙女仆・护育龙女', 'ドラゴンメイド・ナサリー', 'Effect Monster', 'Dragon', 'EARTH', 2, 500, 1600, '这个卡名的①②的效果1回合各能使用1次。 ①：这张卡召唤·特殊召唤的场合，以除「半龙女仆·育婴龙女」外的自己墓地1只4星以下的「半龙女仆」怪兽为对象才能发动。那只怪兽特殊召唤。 ②：自己·对方的战斗阶段开始时才能发动。这张卡回到手卡，从自己的手卡·墓地把1只7星「半龙女仆」怪兽特殊召唤。'),
(29389368, 'Nutrient Z', '体力增强剂 超级Z', '体力増強剤スーパーZ', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '①：自己要受到2000以上的战斗伤害的场合，那次伤害计算时才能发动。自己回复4000基本分。'),
(12953226, 'Nuvia the Wicked', '女邪神 努维娅', '女邪神ヌヴィア', 'Effect Monster', 'Fiend', 'DARK', 4, 2000, 800, '召唤的场合，这张卡破坏。对方有怪兽控制的场合，对方场上每有1张可控制的怪兽这张卡的攻击力下降200。'),
(63703130, 'O - Oversoul', 'O－超越灵魂', 'O－オーバーソウル', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '①：以自己墓地1只「元素英雄」通常怪兽为对象才能发动。那只怪兽特殊召唤。'),
(14920218, 'Oafdragon Magician', '贱龙的魔术师', '賤竜の魔術師', 'Pendulum Effect Monster', 'Spellcaster', 'WIND', 6, 2100, 1400, '这个卡名的怪兽效果1回合只能使用1次。 ①：这张卡召唤·特殊召唤的场合，以自己墓地1只「贱龙之魔术师」以外的「魔术师」灵摆怪兽或「异色眼」怪兽为对象才能发动。那只怪兽加入手卡。'),
(39122311, 'Oasis of Dragon Souls', '龙魂之幻泉', '竜魂の幻泉', 'Trap Card', 'Continuous', NULL, NULL, NULL, NULL, '①：以自己墓地1只怪兽为对象才能把这张卡发动。那只怪兽守备表示特殊召唤。只要这张卡在魔法与陷阱区域存在，特殊召唤的那只怪兽的种族变成幻龙族。这张卡从场上离开时那只怪兽破坏。那只怪兽从场上离开时这张卡破坏。'),
(99311109, 'Oath of Companionship', '战友的誓言', '戦友の誓い', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '从额外卡组特殊召唤的怪兽不在自己场上存在的场合，选择对方场上表侧表示存在的1只从额外卡组特殊召唤的怪兽才能发动。选择的怪兽的控制权直到结束阶段时得到。这张卡发动的回合，自己不能把怪兽特殊召唤。'),
(72537897, 'Obedience Schooled', '魔兽之怀柔', '魔獣の懐柔', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '①：自己场上没有怪兽存在的场合才能发动。把3只卡名不同的2星以下的兽族效果怪兽从卡组特殊召唤。这个效果特殊召唤的怪兽的效果无效化，结束阶段破坏。这张卡的发动后，直到回合结束时自己不是兽族怪兽不能特殊召唤。'),
(10000000, 'Obelisk the Tormentor', '欧贝利斯克之巨神兵', 'オベリスクの巨神兵', 'Effect Monster', 'Divine-Beast', 'DIVINE', 10, 4000, 4000, '这张卡通常召唤的场合，必须把3只解放作召唤。 ①：这张卡的召唤不会被无效化。 ②：在这张卡的召唤成功时双方不能把卡的效果发动。 ③：双方不能把场上的这张卡作为效果的对象。 ④：把自己场上2只怪兽解放才能发动（这个效果发动的回合，这张卡不能攻击宣言）。对方场上的怪兽全部破坏。 ⑤：这张卡特殊召唤的场合，结束阶段发动。这张卡送去墓地。'),
(56713552, 'Obese Marmot of Nefariousness', '邪恶老鼠', 'イビル・ラット', 'Normal Monster', 'Beast', 'EARTH', 3, 750, 800, '任何东西都咬的野老鼠，行仪极坏。'),
(64043465, 'Obliterate!!!', '魔神火炎炮－艾格佐德之炎', '魔神火炎砲', 'Trap Card', 'Continuous', NULL, NULL, NULL, NULL, '这个卡名的①②的效果1回合只能有1次使用其中任意1个。 ①：以场上1只怪兽为对象才能发动。从手卡·卡组把1只「被封印」怪兽或1张「艾克佐迪亚」卡送去墓地，作为对象的怪兽回到手卡。 ②：这张卡从魔法与陷阱区域送去墓地的场合，以自己墓地1只「被封印」怪兽或1张「艾克佐迪亚」卡为对象才能发动。那张卡加入手卡。'),
(402416, 'Obliterate!!! Blaze', '魔神火焰炮－艾格佐德之焰', '魔神火焔砲', 'Spell Card', 'Quick-Play', NULL, NULL, NULL, NULL, '①：原本卡名包含「艾克佐迪亚」的场上1只10星以上的怪兽得到以下效果。 ●把基本分支付一半才能发动。双方的魔法与陷阱区域的卡全部破坏。那之后，从手卡·卡组把5只「被封印」怪兽各当作攻击力上升2000的装备魔法卡使用给这张卡装备。这个效果的发动后，直到回合结束时自己不能把这张卡以外的卡的效果发动。 ●这张卡向守备表示怪兽攻击的场合，给与对方为攻击力超过那个守备力的数值的战斗伤害。'),
(52077741, 'Obnoxious Celtic Guard', '翻弄敌人的精灵剑士', '翻弄するエルフの剣士', 'Effect Monster', 'Warrior', 'EARTH', 4, 1400, 1200, '①：这张卡不会被和攻击力1900以上的怪兽的战斗破坏。'),
(30607616, 'Oboro-Guruma, the Wheeled Mayakashi', '辙之魔妖－胧车', '轍の魔妖－朧車', 'Synchro Monster', 'Zombie', 'EARTH', 3, 800, 2100, '调整＋调整以外的怪兽1只以上 这个卡名的②③的效果1回合各能使用1次。 ①：「辙之魔妖-胧车」在自己场上只能有1只表侧表示存在。 ②：这张卡在墓地存在，原本等级是5星的自己的同调怪兽被战斗或者对方的效果破坏的场合才能发动。从自己墓地把1只其他的不死族怪兽除外，这张卡特殊召唤。 ③：这张卡从墓地的特殊召唤成功的场合才能发动。这个回合，自己怪兽不会被战斗破坏。'),
(98806751, 'Obsessive Uvualoop', '执爱之轮回化勒', '執愛のウヴァループ', 'Tuner Monster', 'Fiend', 'EARTH', 4, 1200, 1800, '这个卡名的①②的效果1回合各能使用1次。 ①：这张卡在手卡存在的场合，以自己的场上·墓地1只同调怪兽为对象才能发动。那只怪兽除外，这张卡特殊召唤。 ②：这张卡在墓地存在的场合，以自己的场上·墓地1只同调怪兽为对象才能发动。那只怪兽除外，这张卡加入手卡。'),
(90464188, 'Obsidian Dragon', '黑曜岩龙', '黒曜岩竜', 'Effect Monster', 'Rock', 'DARK', 4, 800, 2100, '只要这张卡在场上表侧表示存在，自己场上表侧表示存在的1只暗属性怪兽为对象的魔法·陷阱卡的效果无效并破坏。'),
(3055018, 'Obsidim, the Ashened City', '灰灭之都 黑曜城', '灰滅の都 オブシディム', 'Spell Card', 'Field', NULL, NULL, NULL, NULL, '这个卡名的②③的效果1回合各能使用1次。 ①：自己回合内，对方场上的特殊召唤的表侧表示怪兽变成炎族。 ②：自己结束阶段，以自己墓地1张「灰灭之都 奥布西地暮」为对象才能发动。那张卡回到卡组最下面。那之后，自己抽1张。 ③：场地区域的这张卡被破坏的场合或者被除外的场合才能发动。从卡组把1只「灰灭」怪兽特殊召唤。'),
(23931679, 'Ocean Dragon Lord - Kairyu-Shin', '海龙神-利维坦', '海竜神－リバイアサン', 'Effect Monster', 'Sea Serpent', 'WATER', 5, 2000, 1700, '这个卡名的②的效果1回合只能使用1次。 ①：只要场上有「海」存在，水属性以外的表侧表示怪兽在双方场上各自只能有1只存在（双方玩家在自身场上有水属性以外的表侧表示怪兽2只以上存在的场合，直到变成1只为止必须送去墓地）。 ②：自己主要阶段才能发动。从卡组把以下的卡之内任意1张加入手卡。 ●「海」 ●「海龙神」魔法·陷阱卡 ●「潜海」魔法·陷阱卡'),
(10485110, 'Ocean Dragon Lord - Neo-Daedalus', '海龙神-尼奥泰达路斯', '海竜神－ネオダイダロス', 'Effect Monster', 'Sea Serpent', 'WATER', 8, 2900, 1600, '这张卡不能通常召唤。把自己场上存在的1只「海龙-泰达路斯」解放的场合才能特殊召唤。可以通过把自己场上存在的「海」送去墓地，这张卡以外的双方的手卡·场上的卡全部送去墓地。'),
(44728989, 'Ocean of Regeneration', '再生之海', '再生の海', 'Spell Card', 'Continuous', NULL, NULL, NULL, NULL, '这个卡名的①的效果1回合只能使用1次。 ①：以自己墓地1只攻击力1000以下的水属性怪兽为对象才能发动。那只怪兽特殊召唤。这个效果特殊召唤的怪兽在结束阶段破坏。'),
(45045866, 'Ocean''s Keeper', '海洋怪鱼卫士', 'オーシャンズ・オーパー', 'Effect Monster', 'Fish', 'WATER', 3, 1500, 1200, '这张卡攻击守备表示怪兽时，若攻击力超过那个守备力，给与对方基本分那个数值的战斗伤害。这张卡被战斗破坏的场合，从自己卡组把1只「千眼卵鱼」或「母脑鱼」加入手卡。'),
(74637266, 'Octoberser', '章鱼怪', 'オクトバーサー', 'Normal Monster', 'Aqua', 'WATER', 5, 1600, 1400, '鱼的头，章鱼的脚，非常不可思议的生物，用枪发动攻击。'),
(86088138, 'Ocubeam', '耳天使', 'エンゼル・イヤーズ', 'Normal Monster', 'Fairy', 'LIGHT', 5, 1550, 1650, '巨大的耳朵和眼睛能监视周围的一切，相貌可怕的天使。'),
(16691074, 'Odd-Eyes Absolute Dragon', '异色眼绝零龙', 'オッドアイズ・アブソリュート・ドラゴン', 'XYZ Monster', 'Dragon', 'WATER', 7, 2800, 2500, '7星怪兽×2 这个卡名的①②的效果1回合各能使用1次。 ①：自己或对方的怪兽的攻击宣言时，把这张卡1个超量素材取除才能发动。那次攻击无效。那之后，可以从自己的手卡·墓地把1只「异色眼」怪兽特殊召唤。 ②：超量召唤的这张卡被送去墓地的场合才能发动。从额外卡组把「异色眼绝零龙」以外的1只「异色眼」怪兽特殊召唤。'),
(61391302, 'Odd-Eyes Advance Dragon', '异色眼上级龙', 'オッドアイズ・アドバンス・ドラゴン', 'Effect Monster', 'Dragon', 'DARK', 8, 3000, 2500, '这张卡可以把1只5星以上的怪兽解放作上级召唤。这个卡名的②的效果1回合只能使用1次。 ①：这张卡上级召唤的场合才能发动。对方场上1只怪兽破坏，给与对方那只怪兽的原本攻击力数值的伤害。 ②：这张卡战斗破坏怪兽时才能发动。除「异色眼上级龙」外的1只5星以上的怪兽从自己的手卡·墓地守备表示特殊召唤。'),
(16494704, 'Odd-Eyes Advent', '异色眼降临', 'オッドアイズ・アドベント', 'Spell Card', 'Ritual', NULL, NULL, NULL, NULL, '龙族仪式怪兽的降临必需。这个卡名的卡在1回合只能发动1张。 ①：等级合计直到变成仪式召唤的怪兽的等级以上为止，把自己的手卡·场上的灵摆怪兽解放，从自己的手卡·墓地把1只龙族仪式怪兽仪式召唤。对方场上有怪兽2只以上存在，自己场上没有怪兽存在的场合，自己的额外卡组的「异色眼」怪兽也能作为解放的代替而送去墓地。'),
(14105623, 'Odd-Eyes Arc Pendulum Dragon', '异色眼弧灵摆龙', 'オッドアイズ・アークペンデュラム・ドラゴン', 'Pendulum Normal Monster', 'Dragon', 'DARK', 7, 2700, 2000, '雄壮而又美丽的拥有神秘之眼的奇迹之龙。那闪耀着双色光辉的眼睛，映出描绘于天空之中的轨迹。'),
(6218704, 'Odd-Eyes Arcray Dragon', '霸王天龙异色眼弧光龙', '覇王天龍オッドアイズ・アークレイ・ドラゴン', 'Pendulum Effect Fusion Monster', 'Dragon', 'LIGHT', 12, 4000, 4000, '龙族的融合·同调·超量·灵摆怪兽各1只合计4只 这个卡名在规则上当作「霸王龙 扎克」使用。额外卡组的里侧的这张卡用融合召唤以及以下方法才能特殊召唤。 ●把自己场上1只暗属性·12星的「霸王龙 扎克」解放的场合可以从额外卡组特殊召唤。 ①：这张卡从额外卡组特殊召唤的场合才能发动。从卡组把1只灵摆怪兽在自己的灵摆区域放置。 ②：怪兽区域的这张卡被破坏的场合才能发动。这张卡在自己的灵摆区域放置。'),
(53025096, 'Odd-Eyes Dragon', '异色眼龙', 'オッドアイズ・ドラゴン', 'Effect Monster', 'Dragon', 'DARK', 7, 2500, 2000, '①：这张卡战斗破坏对方怪兽送去墓地的场合发动。给与对方那只怪兽的原本攻击力一半数值的伤害。'),
(48144509, 'Odd-Eyes Fusion', '异色眼结合', 'オッドアイズ・フュージョン', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '「异色眼融合」在1回合只能发动1张。 ①：从自己的手卡·场上把龙族融合怪兽卡决定的融合素材怪兽送去墓地，把那1只融合怪兽从额外卡组融合召唤。对方场上有怪兽2只以上存在，自己场上没有怪兽存在的场合，自己的额外卡组的「异色眼」怪兽也能有最多2只作为融合素材。'),
(23851033, 'Odd-Eyes Gravity Dragon', '异色眼重力龙', 'オッドアイズ・グラビティ・ドラゴン', 'Ritual Effect Monster', 'Dragon', 'EARTH', 7, 2800, 2500, '「异色眼降临」降临。「异色眼重力龙」的①的效果1回合只能使用1次。 ①：这张卡特殊召唤成功时才能发动。对方场上的魔法·陷阱卡全部回到持有者手卡。对方不能对应这个效果的发动把魔法·陷阱·怪兽的效果发动。 ②：只要这张卡在怪兽区域存在，对方若不支付500基本分则不能把卡的效果发动。'),
(83347294, 'Odd-Eyes Lancer Dragon', '异色眼枪兵龙', 'オッドアイズ・ランサー・ドラゴン', 'Effect Monster', 'Dragon', 'LIGHT', 8, 3000, 2000, '①：自己场上的灵摆怪兽被战斗·效果破坏的场合，把自己场上1只怪兽解放才能发动。这张卡从手卡特殊召唤。 ②：这张卡攻击的场合，对方直到伤害步骤结束时魔法·陷阱卡不能发动。 ③：自己场上的「异色眼」卡被战斗·效果破坏的场合，可以作为代替把自己的手卡·怪兽区域·灵摆区域1张「异色眼」卡破坏。'),
(80696379, 'Odd-Eyes Meteorburst Dragon', '异色眼陨爆龙', 'オッドアイズ・メテオバースト・ドラゴン', 'Synchro Monster', 'Dragon', 'FIRE', 7, 2500, 2000, '调整＋调整以外的怪兽1只以上 「异色眼陨火龙」的①的效果1回合只能使用1次。 ①：这张卡特殊召唤成功时，以自己的灵摆区域1张卡为对象才能发动。那张卡特殊召唤。这个回合，这张卡不能攻击。 ②：只要这张卡在怪兽区域存在，对方在战斗阶段中不能把怪兽的效果发动。'),
(67754901, 'Odd-Eyes Mirage Dragon', '异色眼幻象龙', 'オッドアイズ・ミラージュ・ドラゴン', 'Pendulum Effect Monster', 'Dragon', 'DARK', 3, 1200, 600, '「异色眼幻象龙」的怪兽效果1回合只能使用1次。 ①：自己的灵摆区域有「异色眼」卡存在的场合，以自己场上1只「异色眼」怪兽为对象才能发动。那只怪兽在这个回合只有1次不会被战斗·效果破坏。这个效果在对方回合也能发动。'),
(16178681, 'Odd-Eyes Pendulum Dragon', '异色眼灵摆龙', 'オッドアイズ・ペンデュラム・ドラゴン', 'Pendulum Effect Monster', 'Dragon', 'DARK', 7, 2500, 2000, '①：这张卡用和对方怪兽的战斗给与对方的战斗伤害变成2倍。'),
(66425726, 'Odd-Eyes Pendulumgraph Dragon', '异色眼灵摆读阵龙', 'オッドアイズ・ペンデュラムグラフ・ドラゴン', 'Pendulum Effect Ritual Monster', 'Dragon', 'LIGHT', 7, 2700, 2500, '「异色眼降临」降临。这张卡用仪式召唤以及从手卡的灵摆召唤才能特殊召唤。 ①：每次对方从额外卡组把怪兽特殊召唤，给与对方300伤害。 ②：1回合1次，对方把魔法卡的效果发动时才能发动。这张卡在自己的灵摆区域放置，那个对方的效果无效。把仪式召唤的这张卡在灵摆区域放置的场合，可以再从额外卡组把1只「异色眼」怪兽特殊召唤。'),
(21250202, 'Odd-Eyes Persona Dragon', '异色眼复面龙', 'オッドアイズ・ペルソナ・ドラゴン', 'Pendulum Effect Monster', 'Dragon', 'DARK', 5, 1200, 2400, '①：1回合1次，以从额外卡组特殊召唤的1只表侧表示怪兽为对象才能发动。那只怪兽的效果直到回合结束时无效。这个效果在对方回合也能发动。'),
(21770839, 'Odd-Eyes Phantasma Dragon', '异色眼幻灵龙', 'オッドアイズ・ファンタズマ・ドラゴン', 'Pendulum Effect Monster', 'Dragon', 'DARK', 8, 3000, 2500, '这个卡名的①②的怪兽效果1回合各能使用1次。 ①：自己的灵摆区域有2张卡存在，自己的额外卡组有表侧表示的「异色眼」灵摆怪兽存在的场合才能发动。这张卡从手卡特殊召唤。这个效果发动的回合，自己不能灵摆召唤。 ②：这张卡向对方怪兽攻击的伤害计算时才能发动。那只对方怪兽的攻击力只在那次伤害计算时下降自己的额外卡组的表侧表示的灵摆怪兽数量×1000。'),
(93149655, 'Odd-Eyes Phantom Dragon', '异色眼魅影龙', 'オッドアイズ・ファントム・ドラゴン', 'Pendulum Effect Monster', 'Dragon', 'DARK', 7, 2500, 2000, '「异色眼幻影龙」的怪兽效果1回合只能使用1次。 ①：灵摆召唤的这张卡的攻击给与对方战斗伤害时才能发动。给与对方为自己的灵摆区域的「异色眼」卡数量×1200伤害。'),
(86238081, 'Odd-Eyes Raging Dragon', '霸王烈龙 异色眼狂怒龙', '覇王烈竜オッドアイズ・レイジング・ドラゴン', 'XYZ Pendulum Effect Monster', 'Dragon', 'DARK', 7, 3000, 2500, '龙族7星怪兽×2 7星可以灵摆召唤的场合在额外卡组的表侧表示的这张卡可以灵摆召唤。 ①：超量怪兽为素材作超量召唤的这张卡得到以下效果。 ●这张卡在同1次的战斗阶段中可以作2次攻击。 ●1回合1次，把这张卡1个超量素材取除才能发动。对方场上的卡全部破坏，这张卡的攻击力直到回合结束时上升破坏的卡数量×200。 ②：怪兽区域的这张卡被破坏的场合才能发动。这张卡在自己的灵摆区域放置。'),
(45627618, 'Odd-Eyes Rebellion Dragon', '霸王黑龙 异色眼反叛龙', '覇王黒竜オッドアイズ・リベリオン・ドラゴン', 'XYZ Pendulum Effect Monster', 'Dragon', 'DARK', 7, 3000, 2500, '龙族7星怪兽×2 7星可以灵摆召唤的场合在额外卡组的表侧的这张卡可以灵摆召唤。 ①：这张卡用超量怪兽为素材作超量召唤的场合发动。对方场上的7星以下的怪兽全部破坏，给与对方破坏数量×1000伤害。这个回合，这张卡在同1次的战斗阶段中可以作3次攻击。 ②：怪兽区域的这张卡被战斗·效果破坏的场合才能发动。自己的灵摆区域的卡全部破坏，这张卡在自己的灵摆区域放置。'),
(98452268, 'Odd-Eyes Rebellion Dragon Overlord', '霸王黑龙 异色眼反叛龙－霸主', '覇王黒竜オッドアイズ・リベリオン・ドラゴン－オーバーロード', 'XYZ Pendulum Effect Monster', 'Dragon', 'DARK', 7, 3000, 2500, '7星怪兽×2 自己对「霸王黑龙 异色眼叛逆龙-霸王」1回合只能有1次特殊召唤。这张卡也能在自己场上的「叛逆」超量怪兽上面重叠来超量召唤，7星可以灵摆召唤的场合在额外卡组的表侧的这张卡可以灵摆召唤。 ①：7阶超量怪兽为素材作超量召唤的这张卡在同1次的战斗阶段中可以作3次攻击。 ②：怪兽区域的这张卡被破坏的场合才能发动。这张卡在自己的灵摆区域放置。'),
(30095833, 'Odd-Eyes Rebellion Xyz Dragon', '霸王黑龙 异色眼反叛超量龙', '覇王黒竜オッドアイズ・リベリオン・エクシーズ・ドラゴン', 'XYZ Pendulum Effect Monster', 'Dragon', 'DARK', 7, 3000, 2500, '7星灵摆怪兽×2 7星可以灵摆召唤的场合在额外卡组的表侧的这张卡可以灵摆召唤。这张卡在超量召唤的回合不能作为超量召唤的素材。这个卡名的①的怪兽效果1回合只能使用1次。 ①：把这张卡1个超量素材取除，以对方场上最多2只攻击力3000以下的怪兽为对象才能发动。那些怪兽破坏。 ②：怪兽区域的这张卡被破坏的场合才能发动。这张卡在自己的灵摆区域放置。'),
(16306932, 'Odd-Eyes Revolution Dragon', '超天新龙 异色眼革命龙', '超天新龍オッドアイズ・レボリューション・ドラゴン', 'Pendulum Effect Monster', 'Dragon', 'LIGHT', 12, -1, -1, '这张卡不能通常召唤。用从手卡的灵摆召唤或者把自己场上的龙族的融合·同调·超量怪兽各1只解放的场合才能特殊召唤。 ①：把这张卡从手卡丢弃，支付500基本分才能发动。从卡组把1只8星以下的龙族灵摆怪兽加入手卡。 ②：这张卡的攻击力·守备力上升对方基本分一半的数值。 ③：1回合1次，把基本分支付一半才能发动。这张卡以外的双方的场上·墓地的卡全部回到持有者卡组。'),
(19221310, 'Odd-Eyes Saber Dragon', '异色眼军刀龙', 'オッドアイズ・セイバー・ドラゴン', 'Effect Monster', 'Dragon', 'LIGHT', 7, 2800, 2000, '①：这张卡在手卡的场合，把自己场上1只光属性怪兽解放才能发动。从手卡·卡组以及自己场上的表侧表示怪兽之中选1只「异色眼龙」送去墓地，这张卡特殊召唤。 ②：这张卡战斗破坏怪兽送去墓地时才能发动。选对方场上1只怪兽破坏。'),
(29325276, 'Odd-Eyes Solblaze Dragon', '异色眼阳焰龙', 'オッドアイズ・ソルブレイズ・ドラゴン', 'Synchro Tuner Monster', 'Dragon', 'LIGHT', 8, 2000, 2500, '调整＋调整以外的怪兽1只以上 这个卡名的①②的效果1回合只能有1次使用其中任意1个。 ①：这张卡特殊召唤的场合才能发动。从自己的额外卡组（表侧）把1只灵摆怪兽特殊召唤。只要这个效果特殊召唤的怪兽在自己场上表侧表示存在，自己不是灵摆怪兽不能特殊召唤。 ②：这张卡在墓地存在的场合，从自己墓地把2只其他的融合·同调·超量·灵摆怪兽除外才能发动。这张卡特殊召唤。'),
(45014450, 'Odd-Eyes Venom Dragon', '霸王紫龙 异色眼猛毒龙', '覇王紫竜オッドアイズ・ヴェノム・ドラゴン', 'Pendulum Effect Fusion Monster', 'Dragon', 'DARK', 10, 3300, 2500, '「凶饿毒」怪兽＋「异色眼」怪兽 这张卡用融合召唤以及灵摆召唤才能特殊召唤。 ①：1回合1次，以对方场上1只表侧表示怪兽为对象才能发动。直到结束阶段，这张卡的攻击力上升那只怪兽的攻击力数值，这张卡得到和那只怪兽相同的原本的卡名·效果。 ②：怪兽区域的这张卡被破坏的场合才能发动。选自己的灵摆区域1张卡特殊召唤，这张卡在自己的灵摆区域放置。'),
(53262004, 'Odd-Eyes Vortex Dragon', '异色眼雷涡龙', 'オッドアイズ・ボルテックス・ドラゴン', 'Fusion Monster', 'Dragon', 'WIND', 7, 2500, 3000, '「异色眼」怪兽＋灵摆怪兽 这个卡名的①②的效果1回合各能使用1次。 ①：这张卡特殊召唤时，以对方场上1只表侧攻击表示怪兽为对象才能发动。那只怪兽回到手卡。 ②：这张卡以外的怪兽的效果·魔法·陷阱卡发动时才能发动。从自己的额外卡组（表侧）让1只灵摆怪兽回到卡组，那个发动无效并破坏。'),
(58074177, 'Odd-Eyes Wing Dragon', '霸王白龙 异色眼辉翼龙', '覇王白竜オッドアイズ・ウィング・ドラゴン', 'Synchro Pendulum Effect Monster', 'Dragon', 'DARK', 8, 3000, 2500, '暗属性调整＋调整以外的「幻透翼」怪兽1只 这个卡名的①②的怪兽效果1回合只能有1次使用其中任意1个。 ①：以对方场上1只效果怪兽为对象才能发动。那只怪兽的效果直到回合结束时无效。 ②：同调召唤的这张卡存在的场合，双方的战斗阶段才能发动。对方场上的5星以上的怪兽全部破坏。 ③：怪兽区域的这张卡被破坏的场合才能发动。这张卡在自己的灵摆区域放置。'),
(85497611, 'Odd-Eyes Wizard Dragon', '异色眼巫师龙', 'オッドアイズ・ウィザード・ドラゴン', 'Effect Monster', 'Dragon', 'DARK', 7, 2500, 2500, '①：这张卡在手卡的场合，把自己场上1只暗属性怪兽解放才能发动。从手卡·卡组以及自己场上的表侧表示怪兽之中选1只「异色眼龙」送去墓地，这张卡特殊召唤。 ②：这张卡被对方破坏送去墓地的场合才能发动。从自己的卡组·墓地选「异色眼魔导龙」以外的1只「异色眼」怪兽特殊召唤。那之后，可以从卡组把1张「螺旋之强袭炸裂」加入手卡。'),
(93483212, 'Odin, Father of the Aesir', '极神圣帝 奥丁', '極神聖帝オーディン', 'Synchro Monster', 'Fairy', 'LIGHT', 10, 4000, 3500, '「极星天」调整＋调整以外的怪兽2只以上 ①：1回合1次，自己主要阶段才能发动。这张卡直到回合结束时不受魔法·陷阱卡的效果影响。 ②：场上的表侧表示的这张卡被对方破坏送去墓地的回合的结束阶段，从自己墓地把1只「极星天」调整除外才能发动。这张卡从墓地特殊召唤。 ③：这张卡的②的效果特殊召唤成功时才能发动。自己从卡组抽1张。'),
(88069166, 'Odin''s Eye', '奥丁之眼', 'オーディンの眼', 'Trap Card', 'Continuous', NULL, NULL, NULL, NULL, '1回合1次，双方的准备阶段时选择自己场上表侧表示存在的1只名字带有「极神」的怪兽才能发动。选择的怪兽的效果直到结束阶段时无效，把对方手卡以及对方场上盖放的卡全部确认。对方不能对应这个效果的发动把魔法·陷阱·效果怪兽的效果发动。'),
(82340056, 'Offering to the Immortals', '荣誉的祭品', '栄誉の贄', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '自己基本分是3000以下的场合，对方宣言直接攻击时才能发动。那只怪兽的攻击无效，在自己场上把2只「祭品石碑衍生物」（岩石族·地·1星·攻/守0）特殊召唤，从自己卡组把1张名字带有「地缚神」的卡加入手卡。「祭品石碑衍生物」不能为名字带有「地缚神」的怪兽的上级召唤以外而解放，也不能作为同调素材。'),
(93217231, 'Offering to the Snake Deity', '毒蛇的供品', '毒蛇の供物', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '①：以自己场上1只爬虫类族怪兽和对方场上2张卡为对象才能发动。那1只自己的爬虫类族怪兽和那2张对方的卡破坏。'),
(19230408, 'Offerings to the Doomed', '给死者的供物', '死者への供物', 'Spell Card', 'Quick-Play', NULL, NULL, NULL, NULL, NULL),
(97565997, 'Ogdoabyss, the Ogdoadic Overlord', '溟界神－八元邃渊', '溟界神－オグドアビス', 'Effect Monster', 'Reptile', 'LIGHT', 10, 3100, 2200, '这个卡名的①②的效果1回合各能使用1次。 ①：这张卡在墓地存在的场合，把自己场上3只怪兽解放才能发动。这张卡特殊召唤。 ②：只在这张卡在场上表侧表示存在才能发动1次。除从墓地特殊召唤的表侧表示怪兽以外的自己·对方场上的怪兽全部送去墓地。这个效果在对方回合也能发动。'),
(23837054, 'Ogdoadic Calling', '溟界之引水蛟', '溟界の呼び蛟', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张。 ①：在自己场上把2只「溟界衍生物」（爬虫类族·暗·2星·攻/守0）特殊召唤。自己墓地有「溟界」怪兽8种类以上存在的场合，可以作为代替让以下效果适用。 ●从自己墓地选2只卡名不同的爬虫类族怪兽特殊召唤。'),
(78789356, 'Ogdoadic Daybreak', '黎溟界辟', '黎溟界闢', 'Spell Card', 'Quick-Play', NULL, NULL, NULL, NULL, '这个卡名的①②的效果1回合各能使用1次。 ①：把自己场上1只爬虫类族怪兽解放才能发动。那只怪兽的等级每2星最多1只的「溟界衍生物」（爬虫类族·暗·2星·攻/守0）在自己场上特殊召唤。 ②：自己主要阶段把墓地的这张卡除外，以自己的除外状态的1只爬虫类族怪兽为对象才能发动。那只怪兽回到卡组。那之后，可以从卡组把1只爬虫类族怪兽送去墓地。'),
(96433300, 'Ogdoadic Hollow', '溟界之虚', '溟界の虚', 'Trap Card', 'Continuous', NULL, NULL, NULL, NULL, '这个卡名的①的效果1回合只能使用1次。 ①：自己·对方的主要阶段，把自己场上1只爬虫类族效果怪兽解放，以对方墓地1只怪兽为对象才能发动。那只怪兽在自己场上特殊召唤。这个效果特殊召唤的怪兽在结束阶段送去墓地。 ②：魔法与陷阱区域的表侧表示的这张卡被送去墓地的场合发动。爬虫类族怪兽以外的自己场上的表侧表示怪兽全部送去墓地。'),
(60448701, 'Ogdoadic Origin', '溟界之渊源', '溟界の淵源', 'Spell Card', 'Field', NULL, NULL, NULL, NULL, '这个卡名的①②的效果1回合各能使用1次。 ①：自己场上的表侧表示的爬虫类族怪兽被战斗或者对方的效果破坏的场合，以对方场上1张卡为对象才能发动。那张卡送去墓地。 ②：场地区域的这张卡被对方的效果破坏的场合才能发动。把自己墓地的爬虫类族怪兽种类数量的卡从对方卡组上面送去墓地。'),
(96203584, 'Ogdoadic Serpent Strike', '溟界之大水蛟', '溟界の大蛟', 'Spell Card', 'Continuous', NULL, NULL, NULL, NULL, '这个卡名的①②的效果1回合各能使用1次。 ①：从自己的手卡·场上把1只怪兽送去墓地，以原本属性和那只怪兽不同的自己墓地1只爬虫类族怪兽为对象才能发动。那只怪兽特殊召唤。 ②：自己·对方的主要阶段，怪兽被送去对方墓地的场合才能发动。从卡组把1只爬虫类族怪兽送去墓地。'),
(24050692, 'Ogdoadic Water Lily', '溟界之蛇睡莲', '溟界の蛇睡蓮', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张。 ①：从卡组把1只爬虫类族怪兽送去墓地。那之后，自己墓地有爬虫类族怪兽5种类以上存在的场合，可以从自己墓地把1只爬虫类族怪兽特殊召唤。'),
(45121025, 'Ogre of the Black Shadow', '黑影之鬼王', '黒い影の鬼王', 'Normal Monster', 'Beast-Warrior', 'EARTH', 4, 1200, 1400, '被黑影附体的恶鬼。用惊人的速度突击。'),
(82670878, 'Ogre of the Scarlet Sorrow', '血泪食人魔', '血涙のオーガ', 'Effect Monster', 'Fiend', 'DARK', 4, NULL, NULL, '对方回合同1次的战斗阶段中宣言第2次的直接攻击时，这张卡可以从手卡特殊召唤。这个效果特殊召唤成功时，这张卡的攻击力·守备力变成和这个回合进行第1次直接攻击的场上表侧表示存在的怪兽相同的数值。这个回合，只要这个效果特殊召唤的这张卡在场上表侧表示存在，对方不能选择这张卡以外的怪兽作为攻击对象。'),
(87313164, 'Oh F!sh!', '大吃鱼惊！', 'ギョッ！', 'Trap Card', 'Counter', NULL, NULL, NULL, NULL, '让从游戏中除外的1只自己的鱼族·海龙族·水族怪兽回到卡组发动。效果怪兽的效果的发动无效并破坏。'),
(97173708, 'Oh Tokenbaum!', '衍生物诞生祭', 'トークン生誕祭', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '把自己场上的相同等级的衍生物2只以上解放才能发动。从自己墓地选择最多有解放的衍生物数量的和为这张卡发动而解放的衍生物相同等级的怪兽特殊召唤。这个效果特殊召唤的怪兽的效果无效化，结束阶段时破坏。'),
(81260679, 'Ohime the Manifested Mikanko', '大日女之御巫', 'オオヒメの御巫', 'Ritual Effect Monster', 'Fairy', 'LIGHT', 6, NULL, NULL, '「御巫神乐」降临 这个卡名的①③的效果1回合各能使用1次。 ①：把手卡的这张卡给对方观看才能发动。从卡组把「大日女之御巫」以外的1张「御巫」卡加入手卡。那之后，选自己1张手卡丢弃。 ②：这张卡不会被战斗破坏，这张卡的战斗发生的对自己的战斗伤害由对方代受。 ③：自己·对方回合，以自己墓地1张装备魔法卡为对象才能发动。那张卡给可以装备的场上1只怪兽装备。'),
(74055055, 'Oil', '石油采掘', '石油採掘', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张。 ①：以自己墓地最多2只4星以下的炎属性怪兽为对象才能发动（同名卡最多1张）。那些怪兽加入手卡。'),
(31768112, 'Oilman', '汽油侠', 'オイルメン', 'Union Effect Monster', 'Machine', 'EARTH', 2, 400, 400, '1回合1次，自己的主要阶段时可以当作装备卡使用给自己场上的机械族怪兽装备，或者把装备解除以表侧攻击表示特殊召唤。只在这个效果当作装备卡使用的场合，装备怪兽战斗破坏对方怪兽的场合，从卡组抽1张卡。（1只怪兽可以装备的同盟最多1张。装备怪兽被破坏的场合，作为代替把这张卡破坏。）'),
(79663524, 'Oily Cicada', '油蝉', 'オイリーゼミ', 'Effect Monster', 'Insect', 'WIND', 3, 1000, 1000, '这个卡名的①②的效果1回合各能使用1次。 ①：这张卡召唤·特殊召唤成功的场合才能发动。自己场上的全部昆虫族怪兽的等级下降1星。 ②：这张卡的表示形式变更的场合才能发动。从自己的手卡·卡组·墓地选1只「油油蝉」特殊召唤。'),
(79335209, 'Ojama Black', '扰乱·黑', 'おジャマ・ブラック', 'Normal Monster', 'Beast', 'LIGHT', 2, NULL, 1000, '据说能使尽一切手段去捣乱的扰乱三人组一员。据说若三人到齐了将会有什么事情发生。'),
(64627453, 'Ojama Blue', '扰乱·蓝', 'おジャマ・ブルー', 'Effect Monster', 'Beast', 'LIGHT', 2, NULL, 1000, '①：这张卡被战斗破坏送去墓地时才能发动。从卡组把2张「扰乱」卡加入手卡。'),
(90011152, 'Ojama Country', '扰乱之乡', 'おジャマ・カントリー', 'Spell Card', 'Field', NULL, NULL, NULL, NULL, '1回合1次，可以从手卡把1张名字带有「扰乱」的卡送去墓地，自己墓地存在的1只名字带有「扰乱」的怪兽特殊召唤。只要自己场上有名字带有「扰乱」的怪兽表侧表示存在，场上表侧表示存在的全部怪兽的原本的攻击力·守备力交换。'),
(8251996, 'Ojama Delta Hurricane!!', '扰乱三角飓风！！', 'おジャマ・デルタハリケーン！！', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '当「扰乱·绿」「扰乱·黄」「扰乱·黑」在自己场上以表侧表示存在时这张卡才能发动。破坏对方场上存在的所有卡。'),
(14470845, 'Ojama Duo', '扰乱二人组', 'おジャマデュオ', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '①：在对方场上把2只「扰乱衍生物」（兽族·光·2星·攻0/守1000）守备表示特殊召唤。这衍生物不能为上级召唤而解放。「扰乱衍生物」被破坏时那控制者受到每1只300伤害。 ②：把墓地的这张卡除外才能发动。从卡组把2只卡名不同的「扰乱」怪兽特殊召唤。这个效果在这张卡送去墓地的回合不能发动。'),
(34031284, 'Ojama Emperor', '扰乱皇帝', 'おジャマ・エンペラー', 'Link Monster', 'Beast', 'LIGHT', NULL, NULL, NULL, '包含「扰乱」怪兽的兽族怪兽3只 这个卡名的③的效果1回合只能使用1次。 ①：场地区域有「扰乱之乡」存在的场合，这张卡攻击力上升3000，不会被效果破坏。 ②：向这张卡的攻击发生的对自己的战斗伤害由对方代受。 ③：以连接怪兽以外的自己墓地1只「扰乱」怪兽为对象才能发动。那只怪兽特殊召唤。这个效果发动过的回合，自己不是融合怪兽不能从额外卡组特殊召唤。'),
(12482652, 'Ojama Green', '扰乱·绿', 'おジャマ・グリーン', 'Normal Monster', 'Beast', 'LIGHT', 2, NULL, 1000, '据说能使尽一切手段去捣乱的扰乱三人组一员。据说若三人到齐了将会有什么事情发生。'),
(90140980, 'Ojama King', '扰乱王', 'おジャマ・キング', 'Fusion Monster', 'Beast', 'LIGHT', 6, NULL, 3000, '「扰乱·绿」＋「扰乱·黄」＋「扰乱·黑」 只要这张卡在场上表侧表示存在，选择对方最多3个怪兽区域不能使用。'),
(40391316, 'Ojama Knight', '扰乱骑士', 'おジャマ・ナイト', 'Fusion Monster', 'Beast', 'LIGHT', 5, NULL, 2500, '「扰乱」怪兽×2 ①：这张卡在怪兽区域表侧表示存在期间，指定没有使用的对方的怪兽区域最多2处，那些区域不能使用。'),
(75884822, 'Ojama Pajama', '扰乱睡衣派对', 'おジャマパーティ', 'Trap Card', 'Continuous', NULL, NULL, NULL, NULL, '这个卡名的①③的效果1回合各能使用1次。 ①：自己·对方的主要阶段才能发动。从卡组把1张「扰乱」卡加入手卡，那之后选1张手卡丢弃。 ②：自己场上的「武装龙」怪兽或者机械族·光属性的融合怪兽被战斗·效果破坏的场合，可以作为代替把自己的手卡·场上·墓地1张「扰乱」卡除外。 ③：这张卡被送去墓地的场合才能发动。除外的自己的「扰乱」怪兽尽可能特殊召唤。'),
(42517468, 'Ojama Pink', '扰乱·粉', 'おジャマ・ピンク', 'Effect Monster', 'Beast', 'LIGHT', 2, NULL, 1000, '这个卡名的效果1回合只能使用1次。 ①：这张卡从手卡·场上送去墓地的场合才能发动。双方玩家从卡组抽1张，那之后选1张手卡丢弃。这个效果让自己把「扰乱」卡丢弃的场合，可以再指定没有使用的对方的怪兽区域1处。那个区域直到对方回合结束时不能使用。'),
(37132349, 'Ojama Red', '扰乱·红', 'おジャマ・レッド', 'Effect Monster', 'Beast', 'LIGHT', 2, NULL, 1000, '这张卡召唤成功时，可以从手卡把名字带有「扰乱」的怪兽最多4只在自己场上攻击表示特殊召唤。'),
(14470846, 'Ojama Token', '扰乱二人组', 'おジャマデュオ', 'Token', 'Beast', NULL, NULL, NULL, NULL, NULL),
(29843091, 'Ojama Trio', '扰乱三人组', 'おジャマトリオ', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '①：在对方场上把3只「扰乱衍生物」（兽族·光·2星·攻0/守1000）守备表示特殊召唤。这衍生物不能为上级召唤而解放。「扰乱衍生物」被破坏时那控制者受到每1只300伤害。'),
(42941100, 'Ojama Yellow', '扰乱·黄', 'おジャマ・イエロー', 'Normal Monster', 'Beast', 'LIGHT', 2, NULL, 1000, '据说能使尽一切手段去捣乱的扰乱三人组一员。据说若三人到齐了将会有什么事情发生。'),
(24643836, 'Ojamagic', '扰乱魔术', 'おジャマジック', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '①：这张卡从手卡·场上送去墓地的场合发动。从卡组把「扰乱·绿」「扰乱·黄」「扰乱·黑」各1只加入手卡。'),
(100000101, 'Ojamandala', NULL, NULL, 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, NULL),
(2390019, 'Ojamassimilation', '扰乱魔改造', 'おジャマ改造', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '①：把额外卡组1只机械族·光属性的融合怪兽给对方观看，把自己的手卡·场上·墓地的「扰乱」怪兽任意数量除外才能发动。从自己的手卡·卡组·墓地选除外的怪兽数量的在给人观看的怪兽有卡名记述的融合素材怪兽特殊召唤（同名卡最多1张）。 ②：把墓地的这张卡除外，以除外的3只自己的「扰乱」怪兽为对象才能发动。那些怪兽加入卡组洗切。那之后，自己从卡组抽1张。'),
(38395123, 'Ojamatch', '扰乱混合赛', 'おジャマッチング', 'Spell Card', 'Quick-Play', NULL, NULL, NULL, NULL, '①：从手卡以及自己场上的表侧表示的卡之中把1张「扰乱」卡送去墓地才能发动。从自己的卡组·墓地选和那张卡卡名不同的1只「扰乱」怪兽和1只「武装龙」怪兽加入手卡。那之后，可以把这个效果加入手卡的1只怪兽召唤。 ②：自己主要阶段把墓地的这张卡除外，以除外的3只自己的「扰乱」怪兽为对象才能发动。那些怪兽加入卡组洗切。那之后，自己从卡组抽1张。'),
(98259197, 'Ojamuscle', '扰乱肌肉', 'おジャマッスル', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '选择场上1只表侧表示存在的「扰乱王」。选择的「扰乱王」以外的名字中带有「扰乱」的怪兽全破坏。每破坏1只怪兽，选择的1只「扰乱王」的攻击力上升1000。'),
(89086647, 'Okiku''s Dish Count', '阿菊的如意算盘', 'お菊さんの皿算用', 'Trap Card', 'Continuous', NULL, NULL, NULL, NULL, '①：对方把卡的效果发动时才能发动（同一连锁上最多1次）。这个效果的发动时积累的连锁数量的盘子指示物给这张卡放置。 ②：这张卡的盘子指示物数量的以下效果适用。 ●9以下：这张卡不会被对方的效果破坏，对方不能把这张卡作为效果的对象。 ●10以上：这张卡送去墓地。 ③：这张卡被自身的效果送去墓地的场合才能发动。从自己卡组上面把10张卡送去墓地。'),
(12948099, 'Old Entity Cthugua', '古神克图格亚', '古神クトグア', 'Synchro Monster', 'Pyro', 'FIRE', 4, 2200, 200, '调整＋调整以外的怪兽1只以上 ①：这张卡同调召唤成功的场合才能发动。场上的4阶超量怪兽全部回到持有者的额外卡组。 ②：这张卡为素材的融合召唤成功的场合发动。自己从卡组抽1张。 ③：场上的这张卡为素材作超量召唤的怪兽得到以下效果。 ●这次超量召唤成功的场合发动。自己从卡组抽1张。'),
(70913714, 'Old Entity Hastorr', '古神 哈斯塔', '古神ハストール', 'Synchro Monster', 'Reptile', 'WIND', 4, 2300, 1000, '调整＋调整以外的怪兽1只以上 ①：这张卡从怪兽区域送去墓地的场合，以对方场上1只表侧表示怪兽为对象才能发动。这张卡当作装备卡使用给那只怪兽装备。装备怪兽不能攻击，效果无效化。 ②：用这张卡的效果给对方怪兽装备的这张卡从场上离开的场合发动。得到这张卡装备过的对方怪兽的控制权。'),
(54239282, 'Old Mind', '抽鬼心', 'オールド・マインド', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张。 ①：把对方手卡随机1张确认。那之后，从以下效果选1个适用。 ●和确认的卡相同种类（怪兽·魔法·陷阱）的自己手卡1张卡和确认的对方的卡丢弃。那之后，场上的这张卡加入对方手卡，自己从卡组抽1张。 ●自己失去1000基本分。'),
(45141844, 'Old Vindictive Magician', '执着的老魔术师', '執念深き老魔術師', 'Flip Effect Monster', 'Spellcaster', 'DARK', 2, 450, 600, '①：这张卡反转的场合，以对方场上1只怪兽为对象发动。那只对方怪兽破坏。'),
(4857085, 'Omega Goggles', 'Ω眼镜', 'Ωメガネ', 'Spell Card', 'Equip', NULL, NULL, NULL, NULL, '这张卡只有自己场上的怪兽才能装备。1回合1次，对方手卡随机选择1张确认。这个效果发动的回合，装备怪兽不能攻击。'),
(53923690, 'Omega Judgment', '欧米伽的制裁', 'オメガの裁き', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '①：以自己的魔法与陷阱区域1张表侧表示的怪兽卡和对方场上2张卡为对象才能发动。那些卡破坏。'),
(47457347, 'Omega Summon', '魔法名－“托梅加瑟利昂”大兽', '魔法名－「大いなる獣」', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '①：以除外的自己的「召唤兽」怪兽任意数量为对象才能发动（同名卡最多1张）。那些怪兽守备表示特殊召唤。'),
(56995655, 'Ominous Fortunetelling', '不吉的占卜', '不吉な占い', 'Trap Card', 'Continuous', NULL, NULL, NULL, NULL, '①：自己准备阶段发动。对方手卡随机选1张，对那张卡的种类（怪兽·魔法·陷阱）作猜测。猜中的场合，给与对方700伤害。'),
(8972398, 'Omni Dragon Brotaur', '妖醒龙幼生巴乌尔', '妖醒龍ラルバウール', 'Effect Monster', 'Dragon', 'DARK', 1, NULL, NULL, '这个卡名的①②的效果1回合各能使用1次。 ①：这张卡在手卡·墓地存在，自己场上的怪兽被战斗或者对方的效果破坏的场合才能发动。这张卡特殊召唤。这个效果特殊召唤的这张卡从场上离开的场合除外。 ②：这张卡特殊召唤成功的场合，以场上1只表侧表示怪兽为对象才能发动。选自己1张手卡丢弃，和作为对象的怪兽相同种族·属性而卡名不同的1只怪兽从卡组加入手卡。'),
(31006879, 'On Your Mark, Get Set, DUEL!', '骑乘决斗！加速！', 'ライディング・デュエル！アクセラレーション！', 'Spell Card', 'Continuous', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张。 ①：作为这张卡的发动时的效果处理，自己场上没有其他卡存在的场合，可以从卡组把1只「同调士」怪兽加入手卡。 ②：自己准备阶段发动。给这张卡放置1个信号指示物。 ③：把自己场上2个信号指示物取除，把魔法与陷阱区域的表侧表示的这张卡送去墓地才能发动。自己抽2张。那之后，选自己1张手卡送去墓地。'),
(91534476, 'One by One', '一接一', 'ワン・バイ・ワン', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张。 ①：从自己的手卡·场上把1只怪兽送去墓地，从自己墓地的怪兽以及除外的自己怪兽之中以送去墓地的怪兽以外的1只1星怪兽为对象才能发动。那只怪兽加入手卡。'),
(33782437, 'One Day of Peace', '暂时休战', '一時休戦', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '①：双方玩家各自从卡组抽1张。直到下次的对方回合结束时，双方受到的全部伤害变成0。'),
(2295440, 'One for One', '一对一', 'ワン・フォー・ワン', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '①：从手卡把1只怪兽送去墓地才能发动。从手卡·卡组把1只1星怪兽特殊召唤。'),
(71275181, 'One of Two', NULL, NULL, 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, NULL),
(74202664, 'One or Eight', '赌一赌八', '一か八か', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张。 ①：自己基本分比对方少的场合才能发动。自己卡组最上面的卡给双方确认，等级是1星或者8星的怪兽的场合，那只怪兽加入手卡或特殊召唤。不是的场合，对方可以从以下效果选1个适用。 ●这张卡的控制者基本分变成1000。 ●从这张卡的控制者来看的对方基本分回复到变成8000。'),
(3606209, 'One Who Hunts Souls', '狩魂者', '魂を狩る者', 'Normal Monster', 'Beast-Warrior', 'EARTH', 4, 1100, 1000, '据说被其用剑斩杀之人的魂魄会离身体而去。'),
(33064647, 'One-Eyed Shield Dragon', '一眼盾龙', '一眼の盾竜', 'Normal Monster', 'Dragon', 'WIND', 3, 700, 1300, '身上的盾不仅能保护身体，还能用来突击。'),
(75620895, 'One-Eyed Skill Gainer', '独眼学艺者', '隻眼のスキル・ゲイナー', 'XYZ Monster', 'Warrior', 'LIGHT', 4, 2500, 2600, '4星怪兽×3 把这张卡1个超量素材取除，选择对方场上1只超量怪兽才能发动。这张卡当作和选择的怪兽同名卡使用，得到相同效果。这个效果只在这张卡在场上表侧表示存在能使用1次。'),
(68223137, 'One-Kuri-Way', '一击库里单行道', 'ワンクリウェイ', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张。 ①：以自己或者对方的墓地1只连接1怪兽为对象才能发动。那只怪兽回到持有者的额外卡组或在持有者场上特殊召唤。'),
(36042825, 'One-Shot Wand', '一击魔杖', 'ワンショット・ワンド', 'Spell Card', 'Equip', NULL, NULL, NULL, NULL, '魔法师族怪兽才能装备。装备怪兽的攻击力上升800。此外，装备怪兽进行战斗的伤害计算后，可以把这张卡破坏并从卡组抽1张卡。'),
(93104632, 'One-Time Passcode', '动态认证码', 'ワンタイム・パスコード', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张。 ①：在自己场上把1只「安全令牌衍生物」（电子界族·光·4星·攻/守2000）守备表示特殊召唤。'),
(89932017, 'One-Way Synchro', '同步独径', 'シンクロ・ワンウェイ', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名的①②的效果1回合只能有1次使用其中任意1个。 ①：从自己的卡组·墓地选1只1星调整加入手卡或特殊召唤。 ②：这张卡在墓地存在，「废品战士」或者有那个卡名记述的怪兽在自己场上存在的场合才能发动。这张卡在自己场上盖放。这个效果盖放的这张卡从场上离开的场合除外。'),
(35187185, 'Oneiros, the Dream Mirror Erlking', '梦魔镜天魔－涅伊洛斯', '夢魔鏡の天魔－ネイロス', 'Fusion Monster', 'Fairy', 'LIGHT', 10, 3000, 3000, '属性不同的「梦魔镜」怪兽×2 这个卡名的②③的效果1回合各能使用1次。 ①：只要这张卡在怪兽区域存在，这张卡的属性也当作「暗」使用。 ②：这张卡以外的自己场上的怪兽被解放的场合，以场上1张卡为对象才能发动。那张卡破坏。 ③：这张卡被对方破坏的场合才能发动。从自己墓地选「梦魔镜的天魔-涅伊洛斯」以外的1只「梦魔镜」怪兽特殊召唤。'),
(37678339, 'Oneiros, the Dream Mirror Tormentor', '梦魔镜魇魔－涅伊洛斯', '夢魔鏡の魘魔－ネイロス', 'Fusion Monster', 'Fiend', 'DARK', 10, 3000, 3000, '属性不同的「梦魔镜」怪兽×2 这个卡名的②③的效果1回合各能使用1次。 ①：只要这张卡在怪兽区域存在，这张卡的属性也当作「光」使用。 ②：场地区域有「黯黑之梦魔镜」存在，怪兽的效果发动时才能发动。那个效果无效。 ③：场地区域有「圣光之梦魔镜」存在的场合，把这张卡解放才能发动。从额外卡组把1只「梦魔镜的天魔-涅伊洛斯」守备表示特殊召唤。这个效果在对方回合也能发动。'),
(66927994, 'Oni Tank T-34', '鬼坦克T-34', '鬼タンクT－３４', 'Normal Monster', 'Machine', 'EARTH', 4, 1400, 1700, '被移植了鬼的灵魂，对有意识的敌人穷追不舍。'),
(90470931, 'Oni-Gami Combo', '鬼神的连击', '鬼神の連撃', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '选择自己场上表侧表示存在的1只超量怪兽，把那些超量素材全部取除发动。这个回合，选择的怪兽在同1次的战斗阶段中可以作2次攻击。'),
(9486959, 'Onibimaru Soul Sweeper', '神隐鬼火丸', '神隠し鬼火丸', 'XYZ Monster', 'Fiend', 'DARK', 2, 1900, 1600, '2星怪兽×2只以上 这个卡名的①②的效果1回合各能使用1次。 ①：把这张卡1个超量素材取除，以对方场上1只怪兽为对象才能发动。那只怪兽直到对方结束阶段除外。 ②：持有超量素材的这张卡被对方破坏的场合，以最多有这张卡持有的超量素材数量的自己·对方的除外状态的怪兽为对象才能发动。那些怪兽回到卡组。'),
(73820802, 'Onikuji', '鬼签', '鬼くじ', 'Trap Card', 'Continuous', NULL, NULL, NULL, NULL, '①：自己准备阶段把这个效果发动。对方宣言卡的种类（怪兽·魔法·陷阱）。自己卡组最上面的卡翻开，翻开的卡是宣言的种类的卡的场合，对方从卡组抽1张。不是的场合，对方手卡随机选1张丢弃。翻开的卡回到卡组最下面。'),
(95990456, 'Onmoraki', '阴魔罗鬼', '陰魔羅鬼', 'Effect Monster', 'Zombie', 'EARTH', 4, 1200, 1000, '这个卡名的效果1回合只能使用1次。 ①：这张卡被对方的效果破坏送去墓地的场合或者从墓地的特殊召唤成功的场合才能发动。自己从卡组抽1张。'),
(55088578, 'Onomatokage', '拟声蜥蜴', 'オノマトカゲ', 'Effect Monster', 'Reptile', 'DARK', 4, 1100, 1500, '这个卡名在规则上也当作「刷拉拉」、「我我我」、「隆隆隆」、「怒怒怒」卡使用。这个卡名的①②的效果1回合各能使用1次。 ①：这张卡在手卡·墓地存在，自己场上有「刷拉拉」、「我我我」、「隆隆隆」、「怒怒怒」怪兽的其中任意种存在的场合才能发动。这张卡特殊召唤。这个效果特殊召唤的这张卡从场上离开的场合除外。 ②：把墓地的这张卡除外才能发动。从自己墓地让最多2只超量怪兽回到额外卡组。'),
(6595475, 'Onomatopaira', '拟声连携', 'オノマト連携', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张。 ①：把1张手卡送去墓地才能发动。从卡组把以下怪兽之内各1只合计最多2只加入手卡。 ●「刷拉拉」怪兽 ●「我我我」怪兽 ●「隆隆隆」怪兽 ●「怒怒怒」怪兽'),
(26493435, 'Onomatopia', '希望乡－拟声乌托邦－', '希望郷－オノマトピア－', 'Spell Card', 'Field', NULL, NULL, NULL, NULL, '①：只要这张卡在场地区域存在，每次自己场上有「希望皇 霍普」怪兽特殊召唤，给这张卡放置1个毅飞冲天指示物。 ②：自己场上的怪兽的攻击力·守备力上升这张卡的毅飞冲天指示物数量×200。 ③：1回合1次，把这张卡2个毅飞冲天指示物取除才能发动。从卡组把「刷拉拉」、「我我我」、「隆隆隆」、「怒怒怒」怪兽之内任意1只特殊召唤。'),
(85119159, 'Onomatopickup', '拟声选择', 'オノマト選択', 'Spell Card', 'Continuous', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张，这个卡名的②的效果1回合只能使用1次。 ①：作为这张卡的发动时的效果处理，可以从卡组把「拟声选择」以外的1张「拟声」卡加入手卡。 ②：以自己场上的「刷拉拉」、「我我我」、「隆隆隆」、「怒怒怒」怪兽之内任意1只为对象才能发动。自己场上的全部怪兽的等级直到回合结束时变成和作为对象的怪兽相同等级。'),
(22993208, 'Onslaught of the Fire Kings', '炎王的急袭', '炎王の急襲', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张。 ①：只有对方场上才有怪兽存在的场合才能发动。从卡组把1只兽族·兽战士族·鸟兽族的炎属性怪兽特殊召唤。这个效果特殊召唤的怪兽的效果无效化，结束阶段破坏。'),
(58861941, 'Ooguchi', '巨口', 'ラージマウス', 'Effect Monster', 'Aqua', 'WATER', 1, 300, 250, '这张卡可以直接攻击对方玩家。'),
(19523799, 'Ookazi', '昼夜的大火灾', '昼夜の大火事', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '给与对方基本分800分伤害。'),
(55573346, 'Oops!', '误爆', '誤爆', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '①：以自己场上1张卡为对象才能发动。那张卡破坏。'),
(80312545, 'Opening of the Spirit Gates', '七精解门', '七精の解門', 'Spell Card', 'Continuous', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张。 ①：作为这张卡的发动时的效果处理，把「神炎皇 乌利亚」「降雷皇 哈蒙」「幻魔皇 拉比艾尔」的其中1只或者有那其中任意种的卡名记述的1只怪兽从卡组加入手卡。 ②：1回合1次，丢弃1张手卡才能发动。从自己墓地把1只攻击力和守备力是0的恶魔族怪兽特殊召唤。 ③：1回合1次，自己场上有10星怪兽存在的场合才能发动。从自己墓地把1张永续魔法卡加入手卡。'),
(43268675, 'Opera the Melodious Diva', '幻奏的音女 欧佩拉', '幻奏の音女オペラ', 'Effect Monster', 'Fairy', 'LIGHT', 4, 2300, 1000, '①：这张卡在召唤·反转的回合不能攻击。 ②：这张卡成为融合召唤的素材送去墓地的场合才能发动。这个回合，自己场上的「幻奏」怪兽不会被战斗·效果破坏。'),
(58538870, 'Oppressed People', '受弹压的民众', '弾圧される民', 'Normal Monster', 'Aqua', 'WATER', 1, 400, 2000, '坚信着一定会在某一天重新获得自由而暂时忍受着每日痛苦生活的民众。'),
(44762290, 'Opti-Camouflage Armor', '光学迷彩铠甲', '光学迷彩アーマー', 'Spell Card', 'Equip', NULL, NULL, NULL, NULL, '只能给1星的怪兽装备。装备这张卡的怪兽可以对对方进行直接攻击。'),
(14531242, 'Opticlops', '红色独眼巨人', 'レッド・サイクロプス', 'Normal Monster', 'Fiend', 'DARK', 4, 1800, 1700, '为冥王哈帝斯效命的独眼巨人。用尖角把敌人扯成碎片。'),
(33248692, 'Option Hunter', '子机猎手', 'オプションハンター', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '自己场上的怪兽被战斗破坏送去墓地时发动。自己回复破坏怪兽的原本攻击力的数值的基本分。'),
(93130022, 'Option Token', '胜利蛇XX03', 'ビクトリー・バイパー XX０３', 'Token', 'Machine', NULL, NULL, NULL, NULL, NULL),
(79306385, 'Oracle of the Herald', '宣告者之神讬', '宣告者の神託', 'Spell Card', 'Ritual', NULL, NULL, NULL, NULL, '「崇光之宣告者」的降临必需。对方不能对应这张卡的发动把魔法·陷阱·怪兽的效果发动。 ①：从自己的手卡·场上把等级合计直到12以上的怪兽解放，从手卡把「崇光之宣告者」仪式召唤。'),
(42280216, 'Oracle of the Sun', '太阳的神官', '太陽の神官', 'Effect Monster', 'Spellcaster', 'LIGHT', 5, 1000, 2000, '①：只有对方场上才有怪兽存在的场合，这张卡可以从手卡特殊召唤。 ②：场上的这张卡被破坏送去墓地时才能发动。从卡组把1只「赤蚁」或者「苏帕伊」加入手卡。'),
(32354768, 'Oracle of Zefra', '神数的神托', 'セフィラの神託', 'Spell Card', 'Field', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张。 ①：这张卡的发动时从卡组把1只「神数」怪兽加入手卡。 ②：以下怪兽使用「神数」怪兽作仪式召唤或者用「神数」怪兽为素材作特殊召唤时，自己让各自效果1回合各能发动1次。 ●仪式：场上1只怪兽回到卡组。 ●融合：手卡1只怪兽特殊召唤。 ●同调：卡组1只怪兽在卡组最上面放置。 ●超量：从卡组抽1张，那之后丢弃1张手卡。'),
(74115234, 'Orb of Yasaka', '八尺勾玉', '八尺勾玉', 'Spell Card', 'Equip', NULL, NULL, NULL, NULL, '灵魂怪兽才能装备。装备怪兽战斗破坏对方怪兽送去墓地时，自己基本分回复破坏怪兽的原本攻击力的数值。装备怪兽从自己场上回到手卡让这张卡被送去墓地时，这张卡回到手卡。'),
(71071546, 'Orbital 7', '奥比塔尔 ７', 'オービタル ７', 'Effect Monster', 'Machine', 'LIGHT', 4, 500, 2000, '①：这张卡反转的场合发动。给这张卡放置1个遵命指示物。 ②：自己主要阶段，把这张卡的遵命指示物全部取除才能发动。这张卡的攻击力变成2000，这个回合不能直接攻击，结束阶段送去墓地。 ③：把这张卡解放，以自己墓地1只「光子」怪兽或者「银河」怪兽为对象才能发动。那只怪兽加入手卡。'),
(96875080, 'Orbital Bombardment', '大气圈外射击', '大気圏外射撃', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '把自己场上1只名字带有「外星」的怪兽送去墓地发动。场上的1张魔法或者陷阱卡破坏。'),
(44009443, 'Orbital Hydralander', '影星轨道兵器 无双九头蛇', '影星軌道兵器ハイドランダー', 'Effect Monster', 'Machine', 'DARK', 8, 3000, 1500, '这张卡不能通常召唤。自己墓地有怪兽5只以上存在，那些怪兽的卡名全部不同的场合才能特殊召唤。 ①：1回合1次，从自己卡组上面把3张卡送去墓地才能发动。自己墓地的怪兽的卡名全部不同的场合，选场上1张卡破坏。这个效果在对方回合也能发动。'),
(63120904, 'Orca Mega-Fortress of Darkness', '暗黑大要塞鲸', '暗黒大要塞鯱', 'Effect Monster', 'Sea Serpent', 'WATER', 5, 2100, 1200, '祭掉自己场上1只「鱼雷鱼」，破坏对方场上1只怪兽。祭掉自己场上1只「炮弹枪贝」，破坏对方场上1张魔法·陷阱卡。'),
(94046012, 'Orcust Brass Bombard', '自鸣天琴・大炮卡农曲', 'オルフェゴール・カノーネ', 'Tuner Monster', 'Machine', 'DARK', 1, 500, 1900, '这个卡名的效果1回合只能使用1次。 ①：把墓地的这张卡除外才能发动。从手卡把「自奏圣乐·卡农曲大炮」以外的1只「自奏圣乐」怪兽特殊召唤。这个效果的发动后，直到回合结束时自己不是暗属性怪兽不能特殊召唤。'),
(703897, 'Orcust Crescendo', '自鸣天琴・渐强高潮', 'オルフェゴール・クリマクス', 'Trap Card', 'Counter', NULL, NULL, NULL, NULL, '这个卡名的①②的效果1回合只能有1次使用其中任意1个。 ①：自己场上有「自奏圣乐」连接怪兽存在，怪兽的效果·魔法·陷阱卡发动时才能发动。那个发动无效并除外。 ②：把墓地的这张卡除外才能发动（这个效果发动的回合，自己不是机械族·暗属性怪兽不能特殊召唤）。自己的卡组·除外状态的1只机械族·暗属性怪兽加入手卡。'),
(21441617, 'Orcust Cymbal Skeleton', '自鸣天琴・骸骨谐谑曲', 'オルフェゴール・スケルツォン', 'Effect Monster', 'Machine', 'DARK', 3, 1200, 1500, '这个卡名的效果1回合只能使用1次。 ①：把墓地的这张卡除外，以「自奏圣乐·谐谑曲骷髅」以外的自己墓地1只「自奏圣乐」怪兽为对象才能发动。那只怪兽特殊召唤。这个效果的发动后，直到回合结束时自己不是暗属性怪兽不能特殊召唤。'),
(57835716, 'Orcust Harp Horror', '自鸣天琴・魔鬼嬉游曲', 'オルフェゴール・ディヴェル', 'Effect Monster', 'Machine', 'DARK', 4, 1700, 1400, '这个卡名的效果1回合只能使用1次。 ①：把墓地的这张卡除外才能发动。从卡组把「自奏圣乐·嬉游曲恶魔」以外的1只「自奏圣乐」怪兽特殊召唤。这个效果的发动后，直到回合结束时自己不是暗属性怪兽不能特殊召唤。'),
(4055337, 'Orcust Knightmare', '自鸣天琴・梦魇曲', 'オルフェゴール・トロイメア', 'Effect Monster', 'Machine', 'DARK', 7, 100, 2000, '这个卡名的②的效果1回合只能使用1次。 ①：这张卡不会被和连接怪兽的战斗破坏。 ②：把墓地的这张卡除外，以场上1只表侧表示怪兽为对象才能发动。从卡组把「自奏圣乐·梦幻崩影」以外的1只机械族·暗属性怪兽送去墓地，作为对象的怪兽的攻击力直到回合结束时上升送去墓地的怪兽的等级×100。这个效果的发动后，直到回合结束时自己不是暗属性怪兽不能特殊召唤。'),
(29666221, 'Orcustrated Attack', '自鸣天琴・起音', 'オルフェゴール・アタック', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '①：自己或者对方的怪兽的攻击宣言时，把自己场上1只「自奏圣乐」怪兽或者「星遗物」怪兽解放，以对方场上1只怪兽为对象才能发动。那只怪兽除外。'),
(90351981, 'Orcustrated Babel', '自鸣天琴・巴别塔', 'オルフェゴール・バベル', 'Spell Card', 'Field', NULL, NULL, NULL, NULL, '①：只要这张卡在场地区域存在，原本卡名包含「自奏圣乐」的，自己场上的连接怪兽以及自己墓地的怪兽发动的效果变成对方回合也能发动的效果。 ②：这个回合没有送去墓地的这张卡在墓地存在的场合，把1张手卡送去墓地才能发动。这张卡加入手卡。'),
(55051920, 'Orcustrated Core', '自鸣天琴・中核音', 'オルフェゴール・コア', 'Trap Card', 'Continuous', NULL, NULL, NULL, NULL, '①：1回合1次，从自己的场上·墓地把1只怪兽除外，以「自奏圣乐的延音」以外的自己场上1张「自奏圣乐」卡或者「星遗物」卡为对象才能发动。这个回合，那张卡不会成为效果的对象。 ②：这张卡以外的自己场上的「自奏圣乐」卡或者「星遗物」卡被战斗·效果破坏的场合，可以作为代替把这张卡送去墓地。'),
(62834295, 'Orcustrated Einsatz', '自鸣天琴・骤变', 'オルフェゴール・アインザッツ', 'Spell Card', 'Continuous', NULL, NULL, NULL, NULL, '这个卡名的①的效果1回合只能使用1次。 ①：对方对怪兽的召唤·特殊召唤成功的场合才能发动。从手卡·卡组选1只「自奏圣乐」怪兽或者「星遗物」怪兽送去墓地或除外。'),
(47171541, 'Orcustrated Release', '自鸣天琴・释音', 'オルフェゴール・リリース', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张。 ①：把自己场上2只机械族怪兽解放，以自己墓地1只怪兽为对象才能发动。那只怪兽特殊召唤。对方场上有连接怪兽存在的场合，这个效果的对象可以变成2只。'),
(26845680, 'Orcustrated Return', '自鸣天琴・唤魂', 'オルフェゴール・プライム', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张。 ①：从自己的手卡·场上（表侧表示）把1只「自奏圣乐」怪兽或「星遗物」怪兽送去墓地才能发动。自己抽2张。'),
(3134857, 'Orcustrion', '自鸣天琴・奥开斯里特翁', 'オルフェゴール・オーケストリオン', 'Link Monster', 'Machine', 'DARK', NULL, 3000, NULL, '包含「自奏圣乐」怪兽的效果怪兽2只以上 这个卡名的②的效果1回合只能使用1次。 ①：连接状态的这张卡不会被战斗·效果破坏。 ②：以除外的3只自己的机械族怪兽为对象才能发动。那些怪兽回到卡组。对方场上有连接状态的表侧表示怪兽存在的场合，那些怪兽攻击力·守备力变成0，效果无效化。'),
(39537362, 'Ordeal of a Traveler', '旅人的试练', '旅人の試練', 'Trap Card', 'Continuous', NULL, NULL, NULL, NULL, '①：对方怪兽的攻击宣言时1次，可以把这个效果发动。自己1张手卡由对方随机选，对方对那张卡的种类（怪兽·魔法·陷阱）作猜测。猜错的场合，那只攻击怪兽回到持有者手卡。'),
(300302069, 'Order of the Queen', NULL, NULL, 'Skill Card', 'Tania', NULL, NULL, NULL, NULL, NULL),
(78986941, 'Order to Charge', '突击指令', '突撃指令', 'Spell Card', 'Quick-Play', NULL, NULL, NULL, NULL, '①：以衍生物以外的自己场上1只通常怪兽为对象才能发动。那只通常怪兽解放，选对方场上1只怪兽破坏。'),
(39019325, 'Order to Smash', '玉碎指令', '玉砕指令', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '选择自己场上存在的1只2星以下的通常怪兽（衍生物除外）发动。发动之后，祭掉被选择的通常怪兽，破坏对方场上至多2张魔法·陷阱卡。'),
(95239444, 'Orea, the Sylvan High Arbiter', '森罗的镇神 山精', '森羅の鎮神 オレイア', 'XYZ Monster', 'Plant', 'DARK', 7, 2800, 2500, '7星怪兽×2 1回合1次，把自己的手卡·场上1只植物族怪兽送去墓地才能发动。把那个等级数量的卡从卡组上面确认，用喜欢的顺序回到卡组上面。此外，1回合1次，把这张卡1个超量素材取除才能发动。从自己卡组上面把最多3张卡翻开。那之中有植物族怪兽的场合，那些怪兽全部送去墓地，选最多有那个数量的这张卡以外的场上的卡回到手卡。剩下的卡用喜欢的顺序回到卡组下面。'),
(15744417, 'Orgoth the Relentless', '神鬼食人魔', 'ゴッドオーガス', 'Effect Monster', 'Warrior', 'EARTH', 7, 2500, 2450, '①：1回合1次，自己主要阶段才能发动。掷3次骰子。这张卡的攻击力·守备力直到对方回合结束时上升出现的数目合计×100。那之后，出现的数目中的2个是相同的场合，那个相同数目的以下效果适用。出现的数目全部是相同的场合，以下效果全部适用。 ●1·2：这张卡直到对方回合结束时不会被战斗·效果破坏。 ●3·4：自己从卡组抽2张。 ●5·6：这个回合，这张卡可以直接攻击。'),
(7634581, 'Orichalcos Shunoros', '山铜合神偶', 'オレイカルコス・シュノロス', 'Effect Monster', 'Machine', 'DARK', 10, -1, NULL, '这张卡不能通常召唤。这张卡的①的效果可以特殊召唤。 ①：自己的通常怪兽被战斗破坏的场合，伤害步骤结束时才能发动。这张卡从手卡特殊召唤。 ②：这张卡的攻击力上升对方场上的怪兽数量×1000。 ③：只要这张卡在怪兽区域存在，场上的4星通常怪兽不会被效果破坏。'),
(68124775, 'Orient Dragon', '东方龙', 'オリエント・ドラゴン', 'Synchro Monster', 'Dragon', 'WIND', 6, 2300, 1000, '调整＋调整以外的怪兽1只以上 这张卡同调召唤成功时，选择对方场上1只同调怪兽从游戏中除外。'),
(7930346, 'Origami Goddess', '折折纸神', '折々の紙神', 'Effect Monster', 'Fairy', 'DARK', 1, 100, NULL, '①：1回合1次，自己主要阶段才能发动。直到里出现为止进行投掷硬币。表出现的次数每有2次，自己抽1张。 ②：这张卡在怪兽区域存在的状态，每次自己·对方进行投掷硬币发动。那些投掷硬币让表出现的次数每有1次，各让这张卡的攻击力变成2倍来对应1次。'),
(33578406, 'Original Bamboo Sword', '真刀竹光', '真刀竹光', 'Spell Card', 'Equip', NULL, NULL, NULL, NULL, '①：装备怪兽的攻击力上升0。 ②：装备怪兽直接攻击给与战斗伤害时才能发动。对方场上的怪兽全部破坏。 ③：把装备的这张卡送去墓地才能发动。从卡组选「真刀竹光」以外的1张「竹光」装备魔法卡给场上1只表侧表示怪兽装备。'),
(89023486, 'Original Sinful Spoils - Snake-Eye', '原罪宝－蛇眼', '原罪宝－スネークアイ', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名的①②的效果1回合只能有1次使用其中任意1个。 ①：把这张卡以外的自己场上1张表侧表示卡送去墓地才能发动。从手卡·卡组把1只炎属性·1星怪兽特殊召唤。 ②：把墓地的这张卡除外，以自己墓地1只「蛇眼」怪兽或「迪亚贝尔斯塔尔」怪兽为对象才能发动。从卡组把1只炎属性·1星怪兽加入手卡。那之后，作为对象的怪兽回到卡组最下面。'),
(2971090, 'Orion the Battle King', '战神 奥利安', '戦いの神 オリオン', 'Normal Monster', 'Fairy', 'LIGHT', 5, 1800, 1500, '被誉为战神的天使。不过谁也没见过那场战事。'),
(97240499, 'Orphebull the Harmonious Bullfighter Bard', '浑然斗牛诗－俄耳甫布鲁', '渾然たる闘牛詩－オルフェブル', 'Effect Monster', 'Beast-Warrior', 'LIGHT', 8, 3000, 2400, '这张卡不能通常召唤。把这张卡以外的光·暗属性怪兽各2只从自己的手卡·墓地除外的场合才能特殊召唤。 ①：这个方法特殊召唤的这张卡的攻击力上升因为那次特殊召唤而从手卡除外的怪兽数量×1000，同1次的战斗阶段中可以向怪兽作出最多有为那次特殊召唤而从墓地除外的怪兽数量的攻击。 ②：这张卡战斗破坏对方怪兽的伤害计算后才能发动。那只对方怪兽除外。'),
(82065276, 'Oscillo Hero', '电波英雄', 'オシロ・ヒーロー', 'Normal Monster', 'Warrior', 'EARTH', 3, 1250, 700, '从异世界来到这里，稀里糊涂的战士。'),
(71519605, 'Oshaleon', '文色龙', 'オシャレオン', 'Effect Monster', 'Reptile', 'WATER', 3, 1400, 800, '只要这张卡在自己场上表侧攻击表示存在，对方不能选择「文色龙」以外的怪兽作为攻击对象。这张卡被战斗破坏送去墓地时，可以从自己卡组把1只攻击力500以下的爬虫类族怪兽加入手卡。'),
(9113513, 'Ostinato', '反复音型', 'オスティナート', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '①：自己场上没有怪兽存在的场合才能发动。从自己的手卡·卡组把「幻奏」融合怪兽卡决定的2只融合素材怪兽送去墓地，把那1只融合怪兽从额外卡组融合召唤。这个回合的结束阶段，这个效果融合召唤的怪兽破坏，若那一组融合素材怪兽在自己墓地齐集，可以把那一组特殊召唤。'),
(60946968, 'Otherworld - The "A" Zone', '异界空间-A地带', '異界空間－Aゾーン', 'Spell Card', 'Field', NULL, NULL, NULL, NULL, '对方怪兽和自己场上存在的名字带有「外星」的怪兽战斗的场合，对方怪兽的攻击力·守备力只在伤害计算时下降300。'),
(39751094, 'Otohime', '龙宫之姬', '竜宮之姫', 'Spirit Monster', 'Spellcaster', 'LIGHT', 3, NULL, 100, NULL),
(72782945, 'Otonari Thunder', '雷电邻居', 'OToNaRiサンダー', 'Effect Monster', 'Thunder', 'LIGHT', 4, 500, 1200, '这个卡名的①②的效果1回合各能使用1次。 ①：这张卡在手卡·墓地存在，自己场上有雷族怪兽2只以上存在的场合才能发动。这张卡特殊召唤。这个效果特殊召唤的这张卡从场上离开的场合除外。 ②：以自己场上1只超量怪兽为对象才能发动。把包含场上的这张卡的自己的手卡·场上（表侧表示）·墓地2只雷族·光属性·4星怪兽作为成为对象的怪兽的超量素材。'),
(14957440, 'Otoshidamashi', '落魂', '落魂', 'Tuner Monster', 'Beast', 'EARTH', 1, 1000, 1000, '这个卡名的②的效果1回合只能使用1次。 ①：只要自己场上有调整以外的怪兽存在，对方不能选择这张卡作为攻击对象。 ②：怪兽从场上送去对方墓地的场合发动。给这张卡放置1个落魂指示物。那之后，把最多有这张卡的落魂指示物数量的「落魂衍生物」（兽族·地·1星·攻/守?）在自己场上特殊召唤。这衍生物的等级上升这张卡的落魂指示物数量的数值，攻击力·守备力变成那等级×500。'),
(79718768, 'Out of the Blue', '急转直下', '急転直下', 'Spell Card', 'Continuous', NULL, NULL, NULL, NULL, '对方把以墓地存在的卡为对象的魔法·陷阱·效果怪兽的效果发动的场合这张卡破坏。这张卡的效果让这张卡被破坏送去墓地时，对方把墓地存在的卡全部加入卡组洗切。'),
(87263576, 'Outburst Dragon', '爆发龙', 'アウトバースト・ドラゴン', 'Effect Monster', 'Dragon', 'DARK', 8, 2100, 2800, '这个卡名的①②的效果1回合各能使用1次。 ①：自己场上有怪兽存在的场合才能发动。这张卡从手卡特殊召唤。那之后，这张卡以外的自己场上的怪兽全部破坏。只要这个效果特殊召唤的这张卡在怪兽区域表侧表示存在，自己不是暗属性怪兽不能特殊召唤。 ②：对方主要阶段才能发动。用包含这张卡的自己场上的怪兽为连接素材把1只龙族连接怪兽连接召唤。'),
(34945480, 'Outer Entity Azathot', '外神 阿撒托斯', '外神アザトート', 'XYZ Monster', 'Fiend', 'DARK', 5, 2400, NULL, '5星怪兽×3 这张卡也能在自己场上的「外神」超量怪兽上面把这张卡重叠来超量召唤。这张卡不能作为超量召唤的素材。 ①：这张卡超量召唤成功的回合，对方不能把怪兽的效果发动。 ②：这张卡有融合·同调·超量怪兽全部在作为超量素材的场合，把这张卡1个超量素材取除才能发动。对方场上的卡全部破坏。'),
(8809344, 'Outer Entity Nyarla', '外神 奈亚拉', '外神ナイアルラ', 'XYZ Monster', 'Fiend', 'EARTH', 4, NULL, 2600, '4星怪兽×2 ①：这张卡超量召唤成功时，把手卡任意数量丢弃才能发动。这张卡的阶级上升丢弃数量的数值。 ②：1回合1次，这张卡持有超量素材的场合以自己墓地1只怪兽为对象才能发动。这张卡的超量素材全部取除，把作为对象的怪兽在这张卡下面重叠作为超量素材。这张卡的种族·属性变成和这个效果作为超量素材的怪兽的原本的种族·属性相同。'),
(96462121, 'Outrigger Extension', '超接地展开', '超接地展開', 'Spell Card', 'Continuous', NULL, NULL, NULL, NULL, '①：自己场上的机械族超量怪兽不会成为对方的效果的对象。 ②：1回合1次，以自己场上1只「无限起动」超量怪兽为对象才能发动。比那只自己怪兽阶级高2阶的1只机械族超量怪兽在作为对象的怪兽上面重叠当作超量召唤从额外卡组特殊召唤。这个效果的发动后，直到回合结束时自己不是机械族·地属性怪兽不能特殊召唤。'),
(11548522, 'Outstanding Dog Marron', '迷犬玛隆', '迷犬マロン', 'Effect Monster', 'Beast', 'LIGHT', 1, 100, 100, '当这张卡被送去墓地时，将这张卡回到卡组。'),
(71583486, 'Outstanding Dog Mary', '迷犬梅丽', '迷犬メリー', 'Effect Monster', 'Beast', 'LIGHT', 1, 100, 100, '这个卡名的效果1回合只能使用1次。 ①：这张卡被送去墓地的场合，可以从以下效果选择1个发动。 ●这张卡回到卡组最下面。 ●从卡组把1只「迷犬 小栗子」加入手卡，这张卡回到卡组最上面。');